def num_grad(f, w, h=1e-5):
    return (f(w + h) - f(w)) / h

def gd_1d(f, w0, lr, steps):
    w = float(w0)
    for _ in range(steps):
        g = num_grad(f, w)
        w -= lr * g
    return w
